import openpyxl
wb = openpyxl.load_workbook('mimotable_batch1_0304_template_9482_input.xlsx', data_only=False)
gwb = openpyxl.load_workbook('/mnt/hhq/data/data_pipeline/generated_tasks/route_b_mimotable_batch1/passed/template/mimotable_batch1_0304_template_9482_golden.xlsx', data_only=False)
# Compare every non-formula cell value with golden (formula text)
diffs=[]
for ws in wb.worksheets:
    gws = gwb[ws.title]
    for row in ws.iter_rows():
        for c in row:
            gc = gws[c.coordinate]
            if c.data_type == 'f':
                # compare formula text
                if gc.data_type != 'f' or (c.value != gc.value):
                    diffs.append((ws.title, c.coordinate, 'formula', c.value, gc.value))
            else:
                if c.value != gc.value or c.data_type != gc.data_type:
                    diffs.append((ws.title, c.coordinate, 'value', c.value, gc.value, c.data_type, gc.data_type))
print('diffs', len(diffs))
for d in diffs[:50]:
    print(d)
EOF
